import { test, expect } from '@playwright/test';

test.describe('Network Request Timeout Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000'); // Replace with your app's URL
  });

  test('should display retry button when network request times out', async ({ page }) => {
    // Simulate a network timeout
    await page.route('**/api/data', route => route.abort('timeout'));
    await page.click(getByText('Fetch Data')); // Assuming there's a button to fetch data
    const retryButton = await page.getByRole('button', { name: /retry/i });
    await expect(retryButton).toBeVisible();
  });

  test('should retry the request when retry button is clicked', async ({ page }) => {
    // Mock the API response after the retry button is clicked
    await page.route('**/api/data', route => route.fulfill({ status: 200, body: JSON.stringify({ success: true }) }));
    await page.click(getByText('Fetch Data')); // Trigger the timeout
    await page.click(getByRole('button', { name: /retry/i })); // Click the retry button
    const successMessage = await page.getByText('Data fetched successfully'); // Assuming a success message appears
    await expect(successMessage).toBeVisible();
  });
});
